-- Pedidos de compra e recebimentos parciais; estoque muda somente na efetivacao da entrada.
alter table commerce_stock_entries drop constraint if exists commerce_stock_entries_origem_check;
alter table commerce_stock_entries add constraint commerce_stock_entries_origem_check check(origem in('compra_manual','nfe_xml','pedido_compra'));
create table commerce_purchase_orders(id uuid primary key default gen_random_uuid(),numero bigint generated always as identity,business_id uuid not null,owner_id uuid not null,supplier_id uuid not null,status text not null default 'aberto' check(status in('aberto','parcial','recebido','cancelado')),previsao date,observacoes text,created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,business_id,owner_id),foreign key(business_id,owner_id) references commerce_businesses(id,owner_id) on delete cascade,foreign key(supplier_id,business_id,owner_id) references commerce_suppliers(id,business_id,owner_id));
create table commerce_purchase_order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null,business_id uuid not null,owner_id uuid not null,product_id uuid not null,variant_id uuid,descricao text not null,quantidade_pedida numeric(14,4) not null check(quantidade_pedida>0),quantidade_recebida numeric(14,4) not null default 0 check(quantidade_recebida>=0 and quantidade_recebida<=quantidade_pedida),valor_unitario numeric(14,4) not null check(valor_unitario>=0),created_at timestamptz not null default now(),unique(id,business_id,owner_id),foreign key(order_id,business_id,owner_id) references commerce_purchase_orders(id,business_id,owner_id) on delete cascade,foreign key(product_id,business_id,owner_id) references commerce_products(id,business_id,owner_id),foreign key(variant_id,business_id,owner_id) references commerce_product_variants(id,business_id,owner_id));
alter table commerce_stock_entries add column if not exists purchase_order_id uuid;
alter table commerce_stock_entries add constraint commerce_entry_purchase_order_fk foreign key(purchase_order_id,business_id,owner_id) references commerce_purchase_orders(id,business_id,owner_id);
create index commerce_purchase_orders_status_idx on commerce_purchase_orders(business_id,status,created_at desc);create index commerce_purchase_order_items_order_idx on commerce_purchase_order_items(order_id);
alter table commerce_purchase_orders enable row level security;alter table commerce_purchase_order_items enable row level security;
create policy commerce_purchase_orders_module on commerce_purchase_orders for all using(owner_id=commerce_owner_atual() and commerce_tem_modulo('compras')) with check(owner_id=commerce_owner_atual() and commerce_tem_modulo('compras'));
create policy commerce_purchase_order_items_module on commerce_purchase_order_items for all using(owner_id=commerce_owner_atual() and commerce_tem_modulo('compras')) with check(owner_id=commerce_owner_atual() and commerce_tem_modulo('compras'));
create trigger commerce_log_purchase_orders after insert or update or delete on commerce_purchase_orders for each row execute function commerce_log_activity('pedido_compra');

create function commerce_receber_pedido_compra(p_order_id uuid,p_itens jsonb) returns uuid language plpgsql security invoker set search_path=public as $$declare o commerce_purchase_orders%rowtype;i commerce_purchase_order_items%rowtype;j jsonb;q numeric(14,4);total numeric(14,2):=0;eid uuid;begin select * into o from commerce_purchase_orders where id=p_order_id and owner_id=commerce_owner_atual() for update;if not found or o.status not in('aberto','parcial') then raise exception 'Pedido nao aceita recebimento.';end if;if jsonb_typeof(p_itens)<>'array' or jsonb_array_length(p_itens)=0 then raise exception 'Informe os itens recebidos.';end if;for j in select value from jsonb_array_elements(p_itens) loop q:=(j->>'quantidade')::numeric;select * into i from commerce_purchase_order_items where id=(j->>'item_id')::uuid and order_id=o.id and owner_id=o.owner_id for update;if not found or q<=0 or q>i.quantidade_pedida-i.quantidade_recebida then raise exception 'Quantidade recebida invalida.';end if;total:=total+round(q*i.valor_unitario,2);end loop;insert into commerce_stock_entries(business_id,owner_id,supplier_id,purchase_order_id,origem,numero_documento,valor_produtos,valor_total) values(o.business_id,o.owner_id,o.supplier_id,o.id,'pedido_compra','PC-'||o.numero,total,total) returning id into eid;for j in select value from jsonb_array_elements(p_itens) loop q:=(j->>'quantidade')::numeric;select * into i from commerce_purchase_order_items where id=(j->>'item_id')::uuid;insert into commerce_stock_entry_items(entry_id,business_id,owner_id,product_id,variant_id,descricao_documento,quantidade,unidade,valor_unitario,valor_total) select eid,o.business_id,o.owner_id,i.product_id,i.variant_id,i.descricao,q,p.unidade,i.valor_unitario,round(q*i.valor_unitario,2) from commerce_products p where p.id=i.product_id;update commerce_purchase_order_items set quantidade_recebida=quantidade_recebida+q where id=i.id;end loop;update commerce_purchase_orders set status=case when not exists(select 1 from commerce_purchase_order_items where order_id=o.id and quantidade_recebida<quantidade_pedida) then 'recebido' else 'parcial' end,updated_at=now() where id=o.id;return eid;end;$$;
revoke all on function commerce_receber_pedido_compra(uuid,jsonb) from public,anon;grant execute on function commerce_receber_pedido_compra(uuid,jsonb) to authenticated;
